// Mevcut dil
let currentLanguage = 'tr';
// Dil çeviri fonksiyonu (Global)
// Yedek zinciri: seçili dil → İngilizce → anahtarın kendisi. Zincir olmadan
// çevrilmemiş bir anahtar arayüzde ham hâliyle ("stressResults") görünüyordu;
// bu yüzden her yeni anahtarın 33 dile birden yazılması gerekiyordu, aksi hâlde
// eksik kalan dil bozuk metin gösteriyordu. Zincirle eksik çeviri okunur bir
// İngilizceye düşer, ham anahtar hiçbir zaman ekrana çıkmaz.
function t(key) {
    const lang = translations[currentLanguage];
    if (lang && lang[key]) return lang[key];
    const en = translations.en;
    if (en && en[key]) return en[key];
    return key;
}
// Dil değiştirme fonksiyonu
function setLanguage(lang) {
    if (translations[lang]) {
        currentLanguage = lang;
        applyTranslations();
        // Dil değişikliği event'i
        window.dispatchEvent(new CustomEvent('languageChanged', { detail: { language: lang } }));
    }
}
// Çevirileri uygula
function applyTranslations() {
    // data-i18n attribute'lu elementleri güncelle
    document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        const translated = t(key);
        if (translated !== key) {
            el.innerHTML = translated;
        }
    });
    // data-i18n-placeholder attribute'lu elementleri güncelle
    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        const key = el.getAttribute('data-i18n-placeholder');
        const translated = t(key);
        if (translated !== key) {
            el.placeholder = translated;
        }
    });
    // data-i18n-title attribute'lu elementleri güncelle
    document.querySelectorAll('[data-i18n-title]').forEach(el => {
        const key = el.getAttribute('data-i18n-title');
        const translated = t(key);
        if (translated !== key) {
            el.title = translated;
        }
    });
}
// Sayfa yüklendiğinde çevirileri uygula
document.addEventListener('DOMContentLoaded', () => {
    applyTranslations();
});
